                "code": "Example\n\n// Perceptron Object\n\nfunction Perceptron(no, learningRate = 0.00001) {\n\n// Set Initial Values\n\nthis.learnc = learningRate;\n\nthis.bias = 1;\n\n// Compute Random Weights\n\nthis.weights = [];\n\nfor (let i = 0; i <= no; i++) {\n\n  this.weights[i] = Math.random() * 2 - 1;\n\n}\n\n// End Perceptron Object\n\n}",
                "language": "ai",
                "heading": "Example",
