                "content": "Example\n\nfunction XYPlotter(id) {\n\nthis.canvas = document.getElementById(id);\n\nthis.ctx = this.canvas.getContext(\"2d\");\n\nthis.xMin = 0;\n\nthis.yMin = 0;\n\nthis.xMax = this.canvas.width;\n\nthis.yMax = this.canvas.height;\n\n.\n\n.",
