                "content": "Example\n\nthis.plotPoints = function(n, xArr, yArr, color, radius = 3) {\n\n  for (let i = 0; i < n; i++) {\n\n    this.ctx.fillStyle = color;\n\n    this.ctx.beginPath();\n\n    this.ctx.ellipse(xArr[i], yArr[i], radius, radius, 0, 0, Math.PI * 2);\n\n    this.ctx.fill();\n\n  }\n\n}",
